import { sql } from "drizzle-orm";
import {
  bigint,
  boolean,
  check,
  customType,
  date,
  foreignKey,
  index,
  integer,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

// IDs are UUIDv7 generated by PostgreSQL 18 (tech-stack.md §2.2);
// Better Auth is configured with `generateId: false` to use these defaults.
const id = () =>
  uuid("id")
    .primaryKey()
    .default(sql`uuidv7()`);
const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
  timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

// ---------------------------------------------------------------------------
// Better Auth core tables (user, session, account, verification, rate_limit)
// ---------------------------------------------------------------------------

export const user = pgTable("user", {
  id: id(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").notNull().default(false),
  image: text("image"),
  // Account settings (F-043, F-046, F-052). Region is separate from the language (Flow F.1).
  /** UI and mail language: "de" | "en". */
  locale: text("locale").notNull().default("en"),
  /** When the language was last chosen explicitly – the latest explicit choice wins (Flow F.3). */
  localeChosenAt: timestamp("locale_chosen_at", { withTimezone: true }),
  /** ISO 3166-1 country for date formats, week start and holidays, e.g. "DE", "US". */
  country: text("country").notNull().default("GB"),
  /** ISO 3166-2 subdivision for regional holidays, e.g. "DE-BY"; null = nationwide only. */
  subdivision: text("subdivision"),
  /** "auto" (by country) | "mon" | "sun". */
  weekStart: text("week_start").notNull().default("auto"),
  /** Account switch "Reduce motion" (Q17 a): true = always reduced, false = follow the device. */
  reduceMotion: boolean("reduce_motion").notNull().default(false),
  /**
   * Last sign-in or use of the app (throttled to once a day) – inactive accounts are deleted
   * after 24 months, with a notice mail 30 days before (F-043, compliance-checklist §6).
   */
  lastActiveAt: timestamp("last_active_at", { withTimezone: true }).notNull().defaultNow(),
  /** When the inactivity notice was sent; cleared as soon as the account is used again. */
  inactivityNoticeSentAt: timestamp("inactivity_notice_sent_at", { withTimezone: true }),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const session = pgTable(
  "session",
  {
    id: id(),
    token: text("token").notNull().unique(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: uuid("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [index("session_user_id_idx").on(table.userId)],
);

export const account = pgTable(
  "account",
  {
    id: id(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: uuid("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at", { withTimezone: true }),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at", { withTimezone: true }),
    scope: text("scope"),
    password: text("password"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [index("account_user_id_idx").on(table.userId)],
);

export const verification = pgTable(
  "verification",
  {
    id: id(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [index("verification_identifier_idx").on(table.identifier)],
);

export const rateLimit = pgTable("rate_limit", {
  id: id(),
  key: text("key").notNull().unique(),
  count: integer("count").notNull(),
  // Milliseconds since epoch → bigint (exceeds int4).
  lastRequest: bigint("last_request", { mode: "number" }).notNull(),
});

/**
 * Per-address auth events for the rate limits per e-mail address (F-041, R-005 follow-up):
 * code requests and failed verifications. `key` is an HMAC of the normalised address – the
 * address itself is never stored here (also not for addresses without an account).
 */
export const authAttempt = pgTable(
  "auth_attempt",
  {
    id: id(),
    key: text("key").notNull(),
    /** "request" (a code mail was asked for) | "failure" (wrong code or password). */
    kind: text("kind").notNull(),
    createdAt: createdAt(),
  },
  (table) => [
    index("auth_attempt_key_kind_created_idx").on(table.key, table.kind, table.createdAt),
  ],
);

// ---------------------------------------------------------------------------
// Trips (F-001 ff., Increment 2)
// ---------------------------------------------------------------------------

/** Planning phase (sitemap §2). "past" is derived from the dates, never stored. */
export const TRIP_PHASES = ["collecting", "voting", "fixed"] as const;
export type TripPhase = (typeof TRIP_PHASES)[number];

/** Member roles (F-004): exactly one organiser ("Orga" in the UI) per trip in the MVP. */
export const MEMBER_ROLES = ["organizer", "member"] as const;
export type MemberRole = (typeof MEMBER_ROLES)[number];

/** Upper limit of members per trip (PRD Q6; open placeholders count too, F-007). */
export const MAX_TRIP_MEMBERS = 30;

export const trip = pgTable(
  "trip",
  {
    id: id(),
    /** Short, non-speaking id in URLs (/trips/<publicId>) – not a secret (sitemap §4). */
    publicId: text("public_id").notNull().unique(),
    name: text("name").notNull(),
    description: text("description"),
    /** Search range, calendar days in the trip's time zone (ISO dates, inclusive). */
    rangeStart: date("range_start", { mode: "string" }).notNull(),
    rangeEnd: date("range_end", { mode: "string" }).notNull(),
    /** "at least … nights" (1–30) and optional "ideally … nights" (≥ min). */
    minNights: integer("min_nights").notNull(),
    preferredNights: integer("preferred_nights"),
    /** Optional deadline for adding dates (F-017). */
    deadline: date("deadline", { mode: "string" }),
    /** Holiday region of the trip (F-016): ISO 3166-1 country + optional ISO 3166-2 subdivision. */
    holidayCountry: text("holiday_country").notNull(),
    holidaySubdivision: text("holiday_subdivision"),
    /** Language of the organiser at creation – for the link preview (sitemap §4). */
    locale: text("locale").notNull().default("en"),
    /** Invite token, 256 bit base64url (F-002: ≥ 128 bit). Renewing replaces it. */
    inviteToken: text("invite_token").notNull().unique(),
    /** "New members can join" (F-004). */
    joinOpen: boolean("join_open").notNull().default(true),
    phase: text("phase", { enum: TRIP_PHASES }).notNull().default("collecting"),
    /** Fixed dates (F-012, Increment 5) – set together with phase "fixed". */
    fixedStart: date("fixed_start", { mode: "string" }),
    fixedEnd: date("fixed_end", { mode: "string" }),
    /** When the dates were fixed – start of the «Vorfreude» ring (design-system §9.12). */
    fixedAt: timestamp("fixed_at", { withTimezone: true }),
    /** Optional voting deadline (F-017, Flow D.1 #3) – never decides automatically. */
    pollDeadline: date("poll_deadline", { mode: "string" }),
    /** When the vote was started (F-010) – phase «voting» since then. */
    pollStartedAt: timestamp("poll_started_at", { withTimezone: true }),
    /**
     * «Abstimmung abbrechen» (Q21, ux-spec §13.1 a): when and by whom the last vote was
     * cancelled – members see a one-off notice «{Name} hat die Abstimmung abgebrochen.».
     * Cleared when a new vote starts.
     */
    pollCanceledAt: timestamp("poll_canceled_at", { withTimezone: true }),
    pollCanceledBy: uuid("poll_canceled_by").references(() => user.id, { onDelete: "set null" }),
    /**
     * Station V1 «Termin steht» (W16 v2.4, F-053): when the organiser tapped WhatsApp/share/copy
     * in «Allen Bescheid geben». Cleared by every new fixing and by «Festlegung aufheben».
     */
    fixedAnnouncedAt: timestamp("fixed_announced_at", { withTimezone: true }),
    /** Automatic deletion (F-013): the organiser was told 14 days before (notice mail). */
    deletionNoticeSentAt: timestamp("deletion_notice_sent_at", { withTimezone: true }),
    /**
     * Currency of the trip (ISO 4217, features.md R.7) – from the holiday region at creation
     * (EUR, GBP, CHF, USD …). Stays store their own copy; the organiser can change it with
     * Increment 10 (F-035).
     */
    currency: text("currency").notNull().default("EUR"),
    /** «Für wie viele rechnet ihr?» (W18 E.6.2, Should): 1–50, null = automatic. */
    partySizeOverride: integer("party_size_override"),
    /**
     * Range of the latest fixing («2027-06-12/2027-06-19») – kept through «Festlegung aufheben»
     * so a new fixing can tell whether the dates really changed (W18 E.8 / E.14).
     */
    lastFixedRange: text("last_fixed_range"),
    /** Dates were fixed anew with ANOTHER range while stays existed (W18 E.8 notice). */
    stayDatesChangedAt: timestamp("stay_dates_changed_at", { withTimezone: true }),
    /** The organiser closed the «Euer Termin hat sich geändert» notice (for everyone). */
    stayDateNoticeDismissedAt: timestamp("stay_date_notice_dismissed_at", { withTimezone: true }),
    /** «gebucht» was reset by that change – second sentence of the notice, V3 «neu buchen». */
    stayBookingReset: boolean("stay_booking_reset").notNull().default(false),
    /**
     * «Abrechnung abschließen» (F-036, R.8 I10-08): expenses AND settlements are read-only while
     * set; «wieder öffnen» clears both columns.
     */
    costsClosedAt: timestamp("costs_closed_at", { withTimezone: true }),
    costsClosedBy: uuid("costs_closed_by").references(() => user.id, { onDelete: "set null" }),
    /**
     * «Bucht» (F-056, R.9 I11-01): the organiser got the marking automatically at the FIRST
     * fixing (or by migration 0012) – never again automatically afterwards.
     */
    bookerDefaultedAt: timestamp("booker_defaulted_at", { withTimezone: true }),
    /**
     * «Festlegung aufheben» happened at this time and no new fixing since (R.9 I11-10): shared
     * travel details are deleted after 30 days. Cleared by every fixing.
     */
    unfixedAt: timestamp("unfixed_at", { withTimezone: true }),
    /**
     * Fixed anew with ANOTHER range while travel-data requests existed (R.9 I11-10): the
     * deletion date moved – one-off notice for the people asked and for «Bucht» (W20 H.6/H.11).
     */
    travelDatesChangedAt: timestamp("travel_dates_changed_at", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    check("trip_phase_check", sql`${table.phase} in ('collecting', 'voting', 'fixed')`),
    check("trip_currency_check", sql`${table.currency} ~ '^[A-Z]{3}$'`),
    check(
      "trip_party_size_check",
      sql`${table.partySizeOverride} is null or ${table.partySizeOverride} between 1 and 50`,
    ),
    check("trip_range_check", sql`${table.rangeEnd} > ${table.rangeStart}`),
    check("trip_nights_check", sql`${table.minNights} between 1 and 30`),
    check(
      "trip_fixed_check",
      sql`(${table.phase} = 'fixed') = (${table.fixedStart} is not null and ${table.fixedEnd} is not null)`,
    ),
  ],
);

export const tripMember = pgTable(
  "trip_member",
  {
    tripId: uuid("trip_id")
      .notNull()
      .references(() => trip.id, { onDelete: "cascade" }),
    userId: uuid("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    /** Name in this trip (F-003: unique per trip, may differ from the account name). */
    displayName: text("display_name").notNull(),
    role: text("role", { enum: MEMBER_ROLES }).notNull().default("member"),
    joinedAt: timestamp("joined_at", { withTimezone: true }).notNull().defaultNow(),
    /** Availability submitted (F-007 status "abgegeben", Increment 3). */
    submittedAt: timestamp("submitted_at", { withTimezone: true }),
    /** Voted in the current poll (F-007 status "abgestimmt", Increment 5). */
    votedAt: timestamp("voted_at", { withTimezone: true }),
    /** Last change of the own days or comment (F-007: «abgegeben · zuletzt geändert …»). */
    availabilityUpdatedAt: timestamp("availability_updated_at", { withTimezone: true }),
    /** Optional comment for the group (F-005, ≤ 200 characters, «Juli nur mit Kindern»). */
    comment: text("comment"),
    /**
     * One-off feedback after the first submission (F-005, A3/A7): which calendar import would
     * have helped – "apple" | "google" | "outlook" | "other" | "none" | "skipped".
     */
    importFeedback: text("import_feedback"),
    /**
     * Fixed range («2027-05-05/2027-05-10») for which this member has seen the celebration
     * «Es geht los!» (F-012, Q17 b): once per person and fixing, across devices. A different
     * range fixed later celebrates again; the same range does not.
     */
    celebratedFor: text("celebrated_for"),
    /**
     * «{orga} hat den Termin wieder geöffnet» is still to be shown (ux-spec §14.4, R-069): set
     * by «Festlegung aufheben» for members who had celebrated exactly the reopened range, cleared
     * when the notice was shown and by every later phase change (fix, cancel, new vote).
     */
    reopenNoticeDue: boolean("reopen_notice_due").notNull().default(false),
    /** Saw the one-off notice about the cancelled vote (Q21) – compared with trip.pollCanceledAt. */
    pollCancelSeenAt: timestamp("poll_cancel_seen_at", { withTimezone: true }),
    /**
     * UX-8 (F-053, I8-07): arrival day for which this member has seen the small departure-day
     * celebration – once per person and arrival date, across devices. A new fixing with another
     * arrival day celebrates again.
     */
    departureCelebratedOn: date("departure_celebrated_on", { mode: "string" }),
    /**
     * Voluntary payment details for THIS trip (F-036, Q35, R.8 I10-07): a checked, normalised
     * IBAN and/or free text («PayPal: lena.k», ≤ 100). Visible to the members of the trip only,
     * gone with the membership (leaving, removal, account deletion) – never in logs or mails.
     */
    paymentIban: text("payment_iban"),
    paymentNote: text("payment_note"),
    paymentUpdatedAt: timestamp("payment_updated_at", { withTimezone: true }),
    /**
     * Marking «Bucht» (F-056, R.9 Datenhaltung): null = not marked. Ends with the membership
     * (leaving, removal, account deletion). At most 3 per trip – checked under the trip lock.
     */
    bookerSince: timestamp("booker_since", { withTimezone: true }),
    bookerSetBy: uuid("booker_set_by").references(() => user.id, { onDelete: "set null" }),
    /** The marking was taken away at this time – one-off notice in /travel-data (W20 H.9). */
    bookerRevokedAt: timestamp("booker_revoked_at", { withTimezone: true }),
    /** Closed the one-off notice «… hat dich als „Bucht“ markiert» / «… nicht mehr markiert». */
    bookerHintSeenAt: timestamp("booker_hint_seen_at", { withTimezone: true }),
    /** Closed the one-off notice «Eure Reise hat neue Daten …» (W20 H.6/H.11). */
    travelDatesHintSeenAt: timestamp("travel_dates_hint_seen_at", { withTimezone: true }),
  },
  (table) => [
    primaryKey({ columns: [table.tripId, table.userId] }),
    index("trip_member_user_id_idx").on(table.userId),
    // F-003: names unique per trip, case-insensitive – the database guarantees it under
    // parallel renames/joins (R-039); the app checks first and offers a suggestion.
    uniqueIndex("trip_member_trip_name_idx").on(table.tripId, sql`lower(${table.displayName})`),
    uniqueIndex("trip_member_one_organizer_idx")
      .on(table.tripId)
      .where(sql`${table.role} = 'organizer'`),
    check("trip_member_role_check", sql`${table.role} in ('organizer', 'member')`),
    check(
      "trip_member_comment_check",
      sql`${table.comment} is null or char_length(${table.comment}) <= 200`,
    ),
    check(
      "trip_member_payment_check",
      sql`(${table.paymentIban} is null or ${table.paymentIban} ~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]{11,30}$')
        and coalesce(char_length(${table.paymentNote}), 0) <= 100`,
    ),
    check(
      "trip_member_import_feedback_check",
      sql`${table.importFeedback} is null or ${table.importFeedback} in ('apple', 'google', 'outlook', 'other', 'none', 'skipped')`,
    ),
  ],
);

/** Stored day states (F-005). "Geht" is the default and never stored (no row = geht). */
export const AVAILABILITY_STATES = ["maybe", "no"] as const;
export type StoredDayState = (typeof AVAILABILITY_STATES)[number];

/**
 * Own availability per day (F-005, Increment 3): only the exceptions «zur Not» / «geht nicht».
 * The composite foreign key on the membership deletes the days when someone leaves or is
 * removed (F-004/F-013) – no orphaned availability.
 */
export const availability = pgTable(
  "availability",
  {
    tripId: uuid("trip_id").notNull(),
    userId: uuid("user_id").notNull(),
    day: date("day", { mode: "string" }).notNull(),
    state: text("state", { enum: AVAILABILITY_STATES }).notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.tripId, table.userId, table.day] }),
    foreignKey({
      name: "availability_member_fk",
      columns: [table.tripId, table.userId],
      foreignColumns: [tripMember.tripId, tripMember.userId],
    }).onDelete("cascade"),
    check("availability_state_check", sql`${table.state} in ('maybe', 'no')`),
  ],
);

/**
 * Placeholders (F-007): people the organiser expects but who have not joined yet. Each has
 * its own invite link (256 bit like the trip link); whoever joins through it takes the
 * placeholder over (name pre-filled). A claimed placeholder keeps its row so the link can say
 * «already used – you can still join normally» (Flow A.3); it no longer counts or shows.
 * Names are unique per trip together with the members – checked under the trip row lock.
 */
export const tripPlaceholder = pgTable(
  "trip_placeholder",
  {
    id: id(),
    tripId: uuid("trip_id")
      .notNull()
      .references(() => trip.id, { onDelete: "cascade" }),
    displayName: text("display_name").notNull(),
    inviteToken: text("invite_token").notNull().unique(),
    createdAt: createdAt(),
    claimedBy: uuid("claimed_by").references(() => user.id, { onDelete: "set null" }),
    claimedAt: timestamp("claimed_at", { withTimezone: true }),
    /**
     * UX-9 (F-053, I8-04): the organiser marked «{Name} macht ohne App mit» – station V2 counts
     * the placeholder as done. Null = not marked (undo); removed with the placeholder.
     */
    withoutAppAt: timestamp("without_app_at", { withTimezone: true }),
    withoutAppBy: uuid("without_app_by").references(() => user.id, { onDelete: "set null" }),
  },
  (table) => [
    index("trip_placeholder_trip_id_idx").on(table.tripId),
    uniqueIndex("trip_placeholder_trip_name_idx")
      .on(table.tripId, sql`lower(${table.displayName})`)
      .where(sql`${table.claimedAt} is null`),
  ],
);

/**
 * Events for app rate limits outside Better Auth (F-003: joins per trip and IP, failed
 * invite lookups per IP). `key` is an HMAC – IP addresses are never stored here.
 */
export const rateLimitEvent = pgTable(
  "rate_limit_event",
  {
    id: id(),
    key: text("key").notNull(),
    kind: text("kind").notNull(),
    createdAt: createdAt(),
  },
  (table) => [index("rate_limit_event_key_kind_idx").on(table.key, table.kind, table.createdAt)],
);

// ---------------------------------------------------------------------------
// Vote (F-010, F-011, F-012 – Increment 5)
// ---------------------------------------------------------------------------

/** Answers per option (F-011). */
export const VOTE_CHOICES = ["yes", "maybe", "no"] as const;
export type VoteChoice = (typeof VOTE_CHOICES)[number];

/**
 * Options of the trip's vote (F-010): concrete periods (arrival and departure day). One vote
 * per trip in the MVP – it is «open» while the trip is in phase «voting»; options can only be
 * added after the start, never changed (existing votes stay valid). Duplicates are prevented
 * by the unique index.
 */
export const pollOption = pgTable(
  "poll_option",
  {
    id: id(),
    tripId: uuid("trip_id")
      .notNull()
      .references(() => trip.id, { onDelete: "cascade" }),
    startDate: date("start_date", { mode: "string" }).notNull(),
    endDate: date("end_date", { mode: "string" }).notNull(),
    createdAt: createdAt(),
  },
  (table) => [
    uniqueIndex("poll_option_trip_range_idx").on(table.tripId, table.startDate, table.endDate),
    // Target of the composite foreign key of poll_vote (a vote and its option share the trip).
    uniqueIndex("poll_option_id_trip_idx").on(table.id, table.tripId),
    check("poll_option_range_check", sql`${table.endDate} > ${table.startDate}`),
  ],
);

/**
 * One answer per member and option (F-011: «genau eine Stimme») – the primary key makes a
 * double vote impossible, also under parallel requests. Removal/leaving deletes the votes
 * through the membership (F-004); deleting an option or trip cascades too.
 */
export const pollVote = pgTable(
  "poll_vote",
  {
    optionId: uuid("option_id").notNull(),
    tripId: uuid("trip_id").notNull(),
    userId: uuid("user_id").notNull(),
    choice: text("choice", { enum: VOTE_CHOICES }).notNull(),
    updatedAt: updatedAt(),
  },
  (table) => [
    primaryKey({ columns: [table.optionId, table.userId] }),
    index("poll_vote_trip_user_idx").on(table.tripId, table.userId),
    foreignKey({
      name: "poll_vote_option_fk",
      columns: [table.optionId, table.tripId],
      foreignColumns: [pollOption.id, pollOption.tripId],
    }).onDelete("cascade"),
    foreignKey({
      name: "poll_vote_member_fk",
      columns: [table.tripId, table.userId],
      foreignColumns: [tripMember.tripId, tripMember.userId],
    }).onDelete("cascade"),
    check("poll_vote_choice_check", sql`${table.choice} in ('yes', 'maybe', 'no')`),
  ],
);

// ---------------------------------------------------------------------------
// Trip info page (F-033, Increment 8 – W22)
// ---------------------------------------------------------------------------

/** Field limits of the info page (W22 C) – checked in the app (zod) AND by the database. */
export const TRIP_INFO_LIMITS = {
  stayName: 80,
  address: 200,
  meetingPoint: 300,
  emergencyName: 60,
  emergencyPhone: 20,
  notes: 2000,
} as const;

/**
 * Infos of a fixed trip (F-033): address, check-in/-out time, meeting point, the
 * accommodation's emergency contact and free text. 1:1 to the trip, deleted with it (F-013) and
 * kept when the dates are reopened. Trip content – never written to logs or mails. `version`
 * detects concurrent edits (W22 C «… hat die Infos inzwischen geändert»).
 */
export const tripInfo = pgTable(
  "trip_info",
  {
    tripId: uuid("trip_id")
      .primaryKey()
      .references(() => trip.id, { onDelete: "cascade" }),
    stayName: text("stay_name"),
    address: text("address"),
    /** «15:00» – the date is the arrival day of the fixed dates (W22 C). */
    checkIn: text("check_in"),
    /** «10:00» – the date is the departure day. */
    checkOut: text("check_out"),
    meetingPoint: text("meeting_point"),
    emergencyName: text("emergency_name"),
    emergencyPhone: text("emergency_phone"),
    notes: text("notes"),
    /** Last editor – «ehemaliges Mitglied» once the account is gone. */
    updatedBy: uuid("updated_by").references(() => user.id, { onDelete: "set null" }),
    updatedAt: updatedAt(),
    version: integer("version").notNull().default(1),
  },
  (table) => [
    check(
      "trip_info_length_check",
      sql`coalesce(char_length(${table.stayName}), 0) <= 80
        and coalesce(char_length(${table.address}), 0) <= 200
        and coalesce(char_length(${table.meetingPoint}), 0) <= 300
        and coalesce(char_length(${table.emergencyName}), 0) <= 60
        and coalesce(char_length(${table.emergencyPhone}), 0) <= 20
        and coalesce(char_length(${table.notes}), 0) <= 2000`,
    ),
    check(
      "trip_info_time_check",
      sql`(${table.checkIn} is null or ${table.checkIn} ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$')
        and (${table.checkOut} is null or ${table.checkOut} ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$')`,
    ),
  ],
);

// ---------------------------------------------------------------------------
// Places to stay (F-031 stage 1, Increment 9 – features.md R.7, W17/W18)
// ---------------------------------------------------------------------------

export const STAY_PREVIEW_STATES = ["pending", "ok", "none"] as const;
export type StayPreviewState = (typeof STAY_PREVIEW_STATES)[number];

/**
 * Suggested places to stay of a fixed trip (F-031). Trip content – title, note, links and
 * image URLs never go to logs or mails. Only the image URL is stored, never the image (Q34).
 * The picked place («Das wird's») and «gebucht» are columns of the suggestion; a partial unique
 * index guarantees at most one picked place per trip (R.7 Datenhaltung, developer's choice).
 * Deleted with the trip (cascade, F-013); the author becomes «ehemaliges Mitglied» when the
 * account is deleted (set null) or the membership ends (cleared by `removeMember`).
 */
export const tripStay = pgTable(
  "trip_stay",
  {
    id: id(),
    tripId: uuid("trip_id")
      .notNull()
      .references(() => trip.id, { onDelete: "cascade" }),
    url: text("url").notNull(),
    /** Duplicate detection (R.7 I9-02): host without www., no fragment/tracking parameters. */
    urlNormalized: text("url_normalized").notNull(),
    title: text("title").notNull(),
    /** Total price in cents of `currency`; null = no price. */
    priceCents: integer("price_cents"),
    currency: text("currency").notNull(),
    note: text("note"),
    /**
     * `https://…` from a signed link preview – or a demo image of our own under
     * `/demo/stays/…` (demo seed only, served statically, no proxy).
     */
    previewImageUrl: text("preview_image_url"),
    previewSiteName: text("preview_site_name"),
    previewStatus: text("preview_status", { enum: STAY_PREVIEW_STATES })
      .notNull()
      .default("pending"),
    createdBy: uuid("created_by").references(() => user.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    /** «Das wird's» (organiser) – at most one per trip. */
    chosenAt: timestamp("chosen_at", { withTimezone: true }),
    chosenBy: uuid("chosen_by").references(() => user.id, { onDelete: "set null" }),
    /** «gebucht ✓» (organiser in Increment 9) – only for the picked place. */
    bookedAt: timestamp("booked_at", { withTimezone: true }),
    bookedBy: uuid("booked_by").references(() => user.id, { onDelete: "set null" }),
  },
  (table) => [
    index("trip_stay_trip_idx").on(table.tripId, table.createdAt),
    uniqueIndex("trip_stay_trip_url_idx").on(table.tripId, table.urlNormalized),
    // Target of the composite foreign key of trip_stay_rating (rating and stay share the trip).
    uniqueIndex("trip_stay_id_trip_idx").on(table.id, table.tripId),
    uniqueIndex("trip_stay_one_chosen_idx")
      .on(table.tripId)
      .where(sql`${table.chosenAt} is not null`),
    check(
      "trip_stay_length_check",
      sql`char_length(${table.url}) <= 2048 and ${table.url} like 'https://%'
        and char_length(${table.title}) between 1 and 80
        and coalesce(char_length(${table.note}), 0) <= 200
        and coalesce(char_length(${table.previewSiteName}), 0) <= 80`,
    ),
    check(
      "trip_stay_price_check",
      sql`${table.priceCents} is null or ${table.priceCents} between 1 and 100000000`,
    ),
    check("trip_stay_currency_check", sql`${table.currency} ~ '^[A-Z]{3}$'`),
    check(
      "trip_stay_image_check",
      sql`${table.previewImageUrl} is null or (char_length(${table.previewImageUrl}) <= 2048
        and (${table.previewImageUrl} like 'https://%'
          or ${table.previewImageUrl} ~ '^/demo/stays/[a-z0-9-]+[.]svg$'))`,
    ),
    check("trip_stay_preview_check", sql`${table.previewStatus} in ('pending', 'ok', 'none')`),
    check(
      "trip_stay_booked_check",
      sql`${table.bookedAt} is null or ${table.chosenAt} is not null`,
    ),
  ],
);

export const STAY_RATINGS = ["like", "nope"] as const;
export type StayRating = (typeof STAY_RATINGS)[number];

/**
 * One rating per member and suggestion (♥ «Gefällt mir» / ✕ «Eher nicht», F-031). «Offen» = no
 * row. The composite key on the membership deletes the ratings when someone leaves, is removed
 * or deletes the account (R.7 I9-10); the composite key on the suggestion keeps a rating in
 * the trip of its suggestion and deletes it with the suggestion.
 */
export const tripStayRating = pgTable(
  "trip_stay_rating",
  {
    stayId: uuid("stay_id").notNull(),
    tripId: uuid("trip_id").notNull(),
    userId: uuid("user_id").notNull(),
    value: text("value", { enum: STAY_RATINGS }).notNull(),
    ratedAt: timestamp("rated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    primaryKey({ columns: [table.stayId, table.userId] }),
    index("trip_stay_rating_trip_user_idx").on(table.tripId, table.userId),
    foreignKey({
      name: "trip_stay_rating_stay_fk",
      columns: [table.stayId, table.tripId],
      foreignColumns: [tripStay.id, tripStay.tripId],
    }).onDelete("cascade"),
    foreignKey({
      name: "trip_stay_rating_member_fk",
      columns: [table.tripId, table.userId],
      foreignColumns: [tripMember.tripId, tripMember.userId],
    }).onDelete("cascade"),
    check("trip_stay_rating_value_check", sql`${table.value} in ('like', 'nope')`),
  ],
);

/** Stations the organiser can tick «ohne App erledigt» (UX-9) – V3 from Increment 9. */
export const STATION_MARKS = ["V3"] as const;
export type StationMark = (typeof STATION_MARKS)[number];

/** UX-9 per station (W16 v2.7, R.6/R.7): «Haben wir schon / brauchen wir nicht». */
export const tripStationMark = pgTable(
  "trip_station_marks",
  {
    tripId: uuid("trip_id")
      .notNull()
      .references(() => trip.id, { onDelete: "cascade" }),
    station: text("station", { enum: STATION_MARKS }).notNull(),
    setBy: uuid("set_by").references(() => user.id, { onDelete: "set null" }),
    setAt: timestamp("set_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    primaryKey({ columns: [table.tripId, table.station] }),
    check("trip_station_marks_station_check", sql`${table.station} in ('V3')`),
  ],
);

// ---------------------------------------------------------------------------
// Cost splitting (F-035 + F-036 stage 1, Increment 10 – features.md R.8, W19 D)
// ---------------------------------------------------------------------------

export const COST_CATEGORY_VALUES = [
  "accommodation",
  "travel",
  "food",
  "activities",
  "other",
] as const;
export const SPLIT_MODE_VALUES = ["equal", "amounts"] as const;

/**
 * People of the settlement («Parteien», R.8 Begriffe): a member (user_id), an open placeholder
 * (placeholder_id) or a former member (both null, `former_at` set). Created on first use under
 * the trip lock. Deliberately NO foreign key to the membership – a party survives leaving with
 * all its amounts. Names are never stored here (always live from membership/placeholder).
 * `seq` = fixed order in the trip (rest cents, ties).
 */
export const tripCostParty = pgTable(
  "trip_cost_party",
  {
    id: id(),
    tripId: uuid("trip_id")
      .notNull()
      .references(() => trip.id, { onDelete: "cascade" }),
    seq: integer("seq").notNull(),
    userId: uuid("user_id").references(() => user.id, { onDelete: "set null" }),
    placeholderId: uuid("placeholder_id").references(() => tripPlaceholder.id, {
      onDelete: "set null",
    }),
    formerAt: timestamp("former_at", { withTimezone: true }),
    formerNo: integer("former_no"),
    createdAt: createdAt(),
  },
  (table) => [
    uniqueIndex("trip_cost_party_seq_idx").on(table.tripId, table.seq),
    uniqueIndex("trip_cost_party_id_trip_idx").on(table.id, table.tripId),
    uniqueIndex("trip_cost_party_user_idx")
      .on(table.tripId, table.userId)
      .where(sql`${table.userId} is not null`),
    uniqueIndex("trip_cost_party_placeholder_idx")
      .on(table.tripId, table.placeholderId)
      .where(sql`${table.placeholderId} is not null`),
    check(
      "trip_cost_party_kind_check",
      sql`not (${table.userId} is not null and ${table.placeholderId} is not null)`,
    ),
  ],
);

/**
 * Expenses (R.8 Datenhaltung). Amounts in cents of the trip currency at creation; soft delete
 * (`deleted_at`) for «Rückgängig», purged after 24 h by the retention job. `version` protects
 * against silent overwrites (I10-03); `idempotency_key` prevents double bookings (I10-02).
 * Trip content – title, note and amounts never go to logs or mails.
 */
export const tripExpense = pgTable(
  "trip_expense",
  {
    id: id(),
    tripId: uuid("trip_id")
      .notNull()
      .references(() => trip.id, { onDelete: "cascade" }),
    title: text("title").notNull(),
    note: text("note"),
    amountCents: integer("amount_cents").notNull(),
    currency: text("currency").notNull(),
    category: text("category", { enum: COST_CATEGORY_VALUES }),
    spentOn: date("spent_on", { mode: "string" }).notNull(),
    payerPartyId: uuid("payer_party_id").notNull(),
    splitMode: text("split_mode", { enum: SPLIT_MODE_VALUES }).notNull(),
    createdBy: uuid("created_by").references(() => user.id, { onDelete: "set null" }),
    updatedBy: uuid("updated_by").references(() => user.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
    version: integer("version").notNull().default(1),
    deletedAt: timestamp("deleted_at", { withTimezone: true }),
    deletedBy: uuid("deleted_by").references(() => user.id, { onDelete: "set null" }),
    idempotencyKey: text("idempotency_key"),
  },
  (table) => [
    index("trip_expense_trip_spent_idx").on(table.tripId, table.spentOn.desc()),
    uniqueIndex("trip_expense_id_trip_idx").on(table.id, table.tripId),
    uniqueIndex("trip_expense_idempotency_idx")
      .on(table.tripId, table.idempotencyKey)
      .where(sql`${table.idempotencyKey} is not null`),
    index("trip_expense_deleted_idx")
      .on(table.deletedAt)
      .where(sql`${table.deletedAt} is not null`),
    foreignKey({
      name: "trip_expense_payer_fk",
      columns: [table.payerPartyId, table.tripId],
      foreignColumns: [tripCostParty.id, tripCostParty.tripId],
    }),
    check(
      "trip_expense_values_check",
      sql`char_length(${table.title}) between 1 and 60
        and coalesce(char_length(${table.note}), 0) <= 200
        and ${table.amountCents} between 1 and 100000000
        and ${table.currency} ~ '^[A-Z]{3}$'
        and ${table.version} >= 1
        and coalesce(char_length(${table.idempotencyKey}), 0) <= 64`,
    ),
    check(
      "trip_expense_category_check",
      sql`${table.category} is null or ${table.category} in ('accommodation', 'travel', 'food', 'activities', 'other')`,
    ),
    check("trip_expense_split_check", sql`${table.splitMode} in ('equal', 'amounts')`),
  ],
);

/**
 * Shares per party, stored explicitly (R.8 rule 3: computed when saving). A deferred constraint
 * trigger (migration 0011) checks «sum of shares = amount» at commit.
 */
export const tripExpenseShare = pgTable(
  "trip_expense_share",
  {
    expenseId: uuid("expense_id").notNull(),
    tripId: uuid("trip_id").notNull(),
    partyId: uuid("party_id").notNull(),
    shareCents: integer("share_cents").notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.expenseId, table.partyId] }),
    index("trip_expense_share_party_idx").on(table.partyId),
    foreignKey({
      name: "trip_expense_share_expense_fk",
      columns: [table.expenseId, table.tripId],
      foreignColumns: [tripExpense.id, tripExpense.tripId],
    }).onDelete("cascade"),
    foreignKey({
      name: "trip_expense_share_party_fk",
      columns: [table.partyId, table.tripId],
      foreignColumns: [tripCostParty.id, tripCostParty.tripId],
    }),
    check("trip_expense_share_cents_check", sql`${table.shareCents} between 0 and 100000000`),
  ],
);

/** Settlements «A → B: Betrag» (I10-06) – undo = delete the row. */
export const tripSettlement = pgTable(
  "trip_settlement",
  {
    id: id(),
    tripId: uuid("trip_id")
      .notNull()
      .references(() => trip.id, { onDelete: "cascade" }),
    fromPartyId: uuid("from_party_id").notNull(),
    toPartyId: uuid("to_party_id").notNull(),
    amountCents: integer("amount_cents").notNull(),
    markedBy: uuid("marked_by").references(() => user.id, { onDelete: "set null" }),
    markedAt: timestamp("marked_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    index("trip_settlement_trip_idx").on(table.tripId, table.markedAt),
    foreignKey({
      name: "trip_settlement_from_fk",
      columns: [table.fromPartyId, table.tripId],
      foreignColumns: [tripCostParty.id, tripCostParty.tripId],
    }),
    foreignKey({
      name: "trip_settlement_to_fk",
      columns: [table.toPartyId, table.tripId],
      foreignColumns: [tripCostParty.id, tripCostParty.tripId],
    }),
    check(
      "trip_settlement_values_check",
      sql`${table.fromPartyId} <> ${table.toPartyId} and ${table.amountCents} between 1 and 2000000000`,
    ),
  ],
);

// ---------------------------------------------------------------------------
// Personal travel details (F-054 stage 1 + F-056, Increment 11 – features.md R.9, W20 H)
// ---------------------------------------------------------------------------

const bytea = customType<{ data: Buffer; driverData: Buffer }>({
  dataType: () => "bytea",
});

/** Field codes of a request (R.9 «Felder», closed list of stage 1). */
export const TRAVEL_FIELD_CODES = [
  "legal_name",
  "birth_date",
  "sex",
  "nationality",
  "document",
  "document_expiry",
  "issuing_country",
] as const;
export type TravelFieldCode = (typeof TRAVEL_FIELD_CODES)[number];

/** Why a request was closed (null = open). */
export const TRAVEL_CLOSED_REASONS = [
  "done",
  "booker_revoked",
  "requester_left",
  "expired",
  "unfixed",
] as const;
export type TravelClosedReason = (typeof TRAVEL_CLOSED_REASONS)[number];

export const TRAVEL_RECIPIENT_STATES = ["open", "released", "declined", "expired"] as const;
export type TravelRecipientState = (typeof TRAVEL_RECIPIENT_STATES)[number];

/** Values that can be copied one by one (access log `field`, W20 H.7). */
export const TRAVEL_COPY_FIELDS = [
  "given_name",
  "family_name",
  "birth_date",
  "sex",
  "nationality",
  "document_type",
  "document_number",
  "document_expiry",
  "issuing_country",
] as const;
export type TravelCopyField = (typeof TRAVEL_COPY_FIELDS)[number];

/**
 * A request of a «Bucht» person for one purpose (R.9 Datenhaltung). Holds no values – only the
 * hull (purpose, field codes, states, times) that stays until the trip is deleted (D3, «… wurden
 * gelöscht» notices). `used_at`: «Bucht» viewed/copied while everybody had answered (V4 row 2).
 */
export const travelDataRequest = pgTable(
  "travel_data_request",
  {
    id: id(),
    tripId: uuid("trip_id")
      .notNull()
      .references(() => trip.id, { onDelete: "cascade" }),
    requesterId: uuid("requester_id").references(() => user.id, { onDelete: "set null" }),
    purpose: text("purpose").notNull(),
    fields: text("fields").array().notNull(),
    createdAt: createdAt(),
    closedAt: timestamp("closed_at", { withTimezone: true }),
    closedReason: text("closed_reason", { enum: TRAVEL_CLOSED_REASONS }),
    usedAt: timestamp("used_at", { withTimezone: true }),
    idempotencyKey: text("idempotency_key"),
  },
  (table) => [
    index("travel_data_request_trip_idx").on(table.tripId, table.createdAt),
    uniqueIndex("travel_data_request_id_trip_idx").on(table.id, table.tripId),
    uniqueIndex("travel_data_request_idempotency_idx")
      .on(table.tripId, table.idempotencyKey)
      .where(sql`${table.idempotencyKey} is not null`),
    check(
      "travel_data_request_purpose_check",
      sql`char_length(${table.purpose}) between 1 and 60
        and coalesce(char_length(${table.idempotencyKey}), 0) <= 64`,
    ),
    check(
      "travel_data_request_fields_check",
      sql`${table.fields} <@ array['legal_name', 'birth_date', 'sex', 'nationality', 'document', 'document_expiry', 'issuing_country']::text[]
        and 'legal_name' = any(${table.fields})
        and (not ('document_expiry' = any(${table.fields}) or 'issuing_country' = any(${table.fields})) or 'document' = any(${table.fields}))`,
    ),
    check(
      "travel_data_request_closed_check",
      sql`(${table.closedAt} is null) = (${table.closedReason} is null)
        and (${table.closedReason} is null or ${table.closedReason} in ('done', 'booker_revoked', 'requester_left', 'expired', 'unfixed'))`,
    ),
  ],
);

/**
 * One person asked by a request and their answer (R.9). Exactly one of `user_id` (member) or
 * `placeholder_id` (open placeholder – becomes the member when it is claimed). The composite key
 * on the membership deletes the answer (and its release) when the person leaves, is removed or
 * deletes the account – like `availability`.
 */
export const travelDataRecipient = pgTable(
  "travel_data_recipient",
  {
    id: id(),
    requestId: uuid("request_id").notNull(),
    tripId: uuid("trip_id").notNull(),
    userId: uuid("user_id"),
    placeholderId: uuid("placeholder_id").references(() => tripPlaceholder.id, {
      onDelete: "cascade",
    }),
    state: text("state", { enum: TRAVEL_RECIPIENT_STATES }).notNull().default("open"),
    respondedAt: timestamp("responded_at", { withTimezone: true }),
    updatedAt: updatedAt(),
    /** «Ausblenden» of the card «… deine Angaben wurden gelöscht» (W20 H.6). */
    dismissedAt: timestamp("dismissed_at", { withTimezone: true }),
  },
  (table) => [
    index("travel_data_recipient_trip_user_idx").on(table.tripId, table.userId),
    uniqueIndex("travel_data_recipient_user_idx")
      .on(table.requestId, table.userId)
      .where(sql`${table.userId} is not null`),
    uniqueIndex("travel_data_recipient_placeholder_idx")
      .on(table.requestId, table.placeholderId)
      .where(sql`${table.placeholderId} is not null`),
    foreignKey({
      name: "travel_data_recipient_request_fk",
      columns: [table.requestId, table.tripId],
      foreignColumns: [travelDataRequest.id, travelDataRequest.tripId],
    }).onDelete("cascade"),
    foreignKey({
      name: "travel_data_recipient_member_fk",
      columns: [table.tripId, table.userId],
      foreignColumns: [tripMember.tripId, tripMember.userId],
    }).onDelete("cascade"),
    check(
      "travel_data_recipient_kind_check",
      sql`(${table.userId} is null) <> (${table.placeholderId} is null)`,
    ),
    check(
      "travel_data_recipient_state_check",
      sql`${table.state} in ('open', 'released', 'declined', 'expired')`,
    ),
  ],
);

/**
 * The encrypted values of one release (AES-256-GCM, R.9 «Verschlüsselung»): one JSON record of
 * the requested fields, bound to trip + request + person + schema version by the AAD. Hard
 * deleted in every case of R.9 I11-10; never readable without the key outside the database.
 * `consent_*` is the proof of the consent (Art. 7 Abs. 1 DSGVO).
 */
export const travelDataRelease = pgTable(
  "travel_data_release",
  {
    recipientId: uuid("recipient_id")
      .primaryKey()
      .references(() => travelDataRecipient.id, { onDelete: "cascade" }),
    ciphertext: bytea("ciphertext").notNull(),
    nonce: bytea("nonce").notNull(),
    keyId: text("key_id").notNull(),
    schemaVersion: integer("schema_version").notNull(),
    consentAt: timestamp("consent_at", { withTimezone: true }).notNull(),
    consentVersion: integer("consent_version").notNull(),
    consentLocale: text("consent_locale").notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    check(
      "travel_data_release_values_check",
      sql`octet_length(${table.nonce}) = 12 and octet_length(${table.ciphertext}) between 17 and 8192
        and ${table.keyId} ~ '^[a-z0-9-]{1,16}$' and ${table.consentLocale} in ('de', 'en')`,
    ),
  ],
);

/**
 * Access log of a release (R.9 I11-07): who viewed/copied what and when – never the value.
 * Lives exactly as long as the release (cascade); at most 1 000 rows per release.
 */
export const travelDataAccess = pgTable(
  "travel_data_access",
  {
    id: id(),
    recipientId: uuid("recipient_id")
      .notNull()
      .references(() => travelDataRelease.recipientId, { onDelete: "cascade" }),
    actorId: uuid("actor_id").references(() => user.id, { onDelete: "set null" }),
    action: text("action", { enum: ["view", "copy"] }).notNull(),
    field: text("field", { enum: TRAVEL_COPY_FIELDS }),
    at: timestamp("at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    index("travel_data_access_recipient_idx").on(table.recipientId, table.at),
    check(
      "travel_data_access_values_check",
      sql`(${table.action} = 'view' and ${table.field} is null)
        or (${table.action} = 'copy' and ${table.field} in ('given_name', 'family_name', 'birth_date', 'sex', 'nationality', 'document_type', 'document_number', 'document_expiry', 'issuing_country'))`,
    ),
  ],
);

// ---------------------------------------------------------------------------
// Demo inbox (online preview, PRD Q25 – MAIL_TRANSPORT=inbox)
// ---------------------------------------------------------------------------

/**
 * Outgoing mails of the password-protected preview, shown on /demo/postfach instead of being
 * sent (no mail provider in the free preview). Demo data only; rows older than 24 hours are
 * removed on every read/write and by the retention job. Never used in production.
 */
export const demoMail = pgTable(
  "demo_mail",
  {
    id: id(),
    toAddress: text("to_address").notNull(),
    subject: text("subject").notNull(),
    text: text("text").notNull(),
    html: text("html").notNull(),
    /** One-time code of the mail (sign-in, reset, …) for the big «copy» display. */
    code: text("code"),
    /** Magic link (sign-in mail) – opens in the same browser. */
    link: text("link"),
    createdAt: createdAt(),
  },
  (table) => [
    index("demo_mail_created_idx").on(table.createdAt),
    index("demo_mail_to_idx").on(table.toAddress, table.createdAt),
  ],
);
